using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "QuicksandDanceCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/QuicksandDanceCustomDescription", order = 0)]
public class QuicksandDanceCustomDescription : GainSandsOfTimeBasedWhereXCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string localizedOnePlusChanting = base.localizationManager.GetLocalizedOnePlusChanting();
		string actionDescription = (battleAction as QuicksandDanceAction).GainChantingEffectAction.GetActionDescription(GetAmountWithoutEquation(amountModified));
		return GetFormattedDescription(battleAction, localizedOnePlusChanting) + "\n" + actionDescription;
	}
}
